class Animal:
    def __init__(self, name):
        self.name = name

    def speak(self):
        print(self.name + "发出了一声叫")


class Cat(Animal):
    def speak(self):
        print(self.name + "：喵～")


name = input()
a = Animal(name)
c = Cat(name)
a.speak()
c.speak()
print(isinstance(c, Animal))
